const messages = $input.all().map((item) => item.json).filter((message) => !message.author?.bot && String(message.channel_id || '') === '1529722358309584987').sort((a, b) => String(a.id).localeCompare(String(b.id)));
const clean = (value) => String(value || '').trim().normalize('NFKC');
const candidates = [];
for (const message of messages) {
  let content = clean(message.content).replace(/^<@!?\d+>\s*/, '').trim();
  if (!content || content.length > 2000 || content === '@everyone' || content === '@here') continue;
  const command = content.match(/^!(vocab|vocab-batch)\s+([\s\S]+)$/i);
  if (command) {
    let payload;
    try { payload = JSON.parse(command[2].replace(/^```(?:json)?\s*|\s*```$/gi, '')); } catch { continue; }
    const entries = command[1].toLowerCase() === 'vocab' ? [payload] : payload;
    if (!Array.isArray(entries) || entries.length < 1 || entries.length > 50) continue;
    entries.forEach((entry, index) => {
      const word = clean(entry?.word);
      if (word && word.length <= 120) candidates.push({ word, message_id: String(message.id), item_index: index });
    });
    continue;
  }
  if (content.includes('\n') || /^https?:\/\//i.test(content)) continue;
  if (content.length <= 120) candidates.push({ word: content, message_id: String(message.id), item_index: 0 });
}
return [{ json: { candidates } }];

const candidates = $('Normalize Discord Words').first().json.candidates || [];
const matrix = $input.first().json.data || [];
const headers = matrix[0] || [];
const rows = matrix.slice(1).filter((row) => Array.isArray(row) && row.some((value) => value !== ''));
const wordColumn = headers.indexOf('Từ vựng');
const numberColumn = headers.indexOf('Số thứ tự');
if (wordColumn < 0 || numberColumn < 0) throw new Error('AdminVocabulary headers must be: Số thứ tự, Từ vựng, Approval');
const normalize = (value) => String(value || '').trim().normalize('NFKC').toLocaleLowerCase('en-US');
const existing = new Set(rows.map((row) => normalize(row[wordColumn])).filter(Boolean));
const candidate = candidates.find((item) => !existing.has(normalize(item.word)));
if (!candidate) return [];
const nextNumber = rows.reduce((max, row) => Math.max(max, Number(row[numberColumn]) || 0), 0) + 1;
const safeWord = /^[=+\-@]/.test(candidate.word) ? `'${candidate.word}` : candidate.word;
return [{ json: { 'Số thứ tự': nextNumber, 'Từ vựng': safeWord, Approval: '' } }];

const adminMatrix = $('Read Admin Vocabulary Approvals').first().json.data || [];
const adminHeaders = adminMatrix[0] || [];
const adminRows = adminMatrix.slice(1).filter((row) => Array.isArray(row) && row.some((value) => value !== ''));
const contentMatrix = $input.first().json.data || [];
const contentHeaders = contentMatrix[0] || [];
const contentRows = contentMatrix.slice(1).filter((row) => Array.isArray(row) && row.some((value) => value !== ''));
const adminNumber = adminHeaders.indexOf('Số thứ tự');
const adminWord = adminHeaders.indexOf('Từ vựng');
const adminApproval = adminHeaders.indexOf('Approval');
const contentWord = contentHeaders.indexOf('normalized_word');
if ([adminNumber, adminWord, adminApproval, contentWord].some((index) => index < 0)) throw new Error('Required AdminVocabulary or Content headers are missing');
const normalize = (value) => String(value || '').trim().replace(/^'/, '').normalize('NFKC').toLocaleLowerCase('en-US');
const approved = new Set(['ok', 'approved', 'approve', 'yes', 'true', '1', 'đồng ý', 'dong y']);
const existingWords = new Set(contentRows.map((row) => normalize(row[contentWord])).filter(Boolean));
const row = adminRows.find((candidate) => approved.has(normalize(candidate[adminApproval])) && normalize(candidate[adminWord]) && !existingWords.has(normalize(candidate[adminWord])));
if (!row) return [];
const word = String(row[adminWord] || '').replace(/^'/, '').trim();
const normalizedWord = normalize(word);
const hash = (value) => { let result = 2166136261; for (let index = 0; index < value.length; index++) { result ^= value.charCodeAt(index); result = Math.imul(result, 16777619); } return (result >>> 0).toString(16).padStart(8, '0'); };
const number = Number(row[adminNumber]) || 0;
const now = new Date().toISOString();
return [{ json: { content_id: `admin-${number}-${hash(normalizedWord)}`, word, normalized_word: normalizedWord, language: 'en', part_of_speech: '', sense_key: '', meaning_vi: '', context_topic: '', example_en: '', example_vi: '', ipa: '', hook: '', cta: '', template_id: '', source: 'admin_sheet', source_ref: `AdminVocabulary:${number}`, license_note: '', publish_ok: '', review_status: 'needs_review', reviewed_by: '', publish_at: '', status: 'needs_review', claimed_at: '', render_id: '', publish_id: '', published_at: '', error_code: '', dedupe_key: `admin:${hash(normalizedWord)}`, created_at: now, updated_at: now } }];
